<script setup>import SiteHeader from '../Components/SiteHeader.vue';import SiteFooter from '../Components/SiteFooter.vue';import {router} from '@inertiajs/vue3';defineProps({cart:Array});function remove(id){router.delete('/cart/'+id)}function update(id,q){router.patch('/cart/'+id,{quantity:q})}</script>
<template><SiteHeader/><main class="mx-auto max-w-4xl px-5 py-14"><p class="eyebrow">Your cart</p><h1 class="serif mt-2 text-5xl font-bold">Ready when you are.</h1><div v-if="!cart.length" class="mt-10 rounded-3xl border p-8 text-center"><p>Your cart is empty.</p><Link href="/menu" class="mt-5 inline-block rounded-full bg-brown px-6 py-3 font-bold text-cream">Explore the Menu</Link></div><div v-else class="mt-10 space-y-4"><article v-for="line in cart" :key="line.id" class="rounded-3xl border border-brown/10 bg-white/40 p-5"><div class="flex items-start justify-between gap-5"><div><h2 class="serif text-2xl font-bold">{{line.box_name}}</h2><ul v-if="line.selection?.length" class="mt-3 space-y-1 text-sm opacity-65"><li v-for="s in line.selection" :key="s.product_id || s.name">{{s.name}}<span v-if="s.quantity"> × {{s.quantity}}</span></li></ul><p v-if="line.extras" class="mt-2 text-xs opacity-55">Flavor upgrades · {{line.extras}} EGP</p><p v-if="line.kind && line.kind!=='box'" class="mt-2 text-xs uppercase tracking-[.14em] opacity-45">{{line.kind.replaceAll('_',' ')}}</p></div><div class="text-right"><div class="font-bold">{{line.subtotal}} EGP</div><div class="mt-3 flex flex-wrap justify-end gap-2"><button @click="update(line.id,Math.max(1,line.quantity-1))" class="rounded-full border px-3">−</button><span class="px-2 py-1">{{line.quantity}}</span><button @click="update(line.id,line.quantity+1)" class="rounded-full border px-3">+</button><button @click="remove(line.id)" class="ml-2 text-sm underline">Remove</button></div></div></div></article><div class="flex justify-end"><Link href="/checkout" class="rounded-full bg-brown px-8 py-3 font-bold text-cream">Checkout</Link></div></div></main><SiteFooter/></template>